head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf07341";
scwin.vID = undefined;
scwin.dts_examprn = null;
scwin.fn_read_sync = null;
scwin.fn_trs = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.dts_examprn = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsExamprn')) : $c.util.getComponent('dtsExamprn');
        scwin.fn_read_sync = scwin.tx_script_dts_examprn;
        scwin.fn_trs = scwin.sbm_trs_Save;
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf07341.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        const parentWin = $c.win.getParent();
        scwin.vID = parentWin.clickID;
        scwin.fn_read_sync();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07341.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Save_onclick
 * @description btn_Save 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Save_onclick = function () {
    try {
        scwin.fn_trs();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07341.btn_Save_onclick' }); }
};

/**
 * @method
 * @name dts_examprn_onloaderror
 * @description dts_examprn onloaderror 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.dts_examprn_onloaderror = function () {
    try {
        $c.win.alert(scwin.dts_examprn);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf07341.dts_examprn_onloaderror" });
    }
};

/**
 * @method
 * @name trs_Save_onfail
 * @description trs_Save onfail 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_onfail = function () {
    try {
        // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.lc.fn_alertMsg
        $c.lc.fn_alertMsg('F');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf07341.trs_Save_onfail" });
    }
};

/**
 * @method
 * @name trs_Save_onsuccess
 * @description trs_Save onsuccess 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_onsuccess = function () {
    try {
        // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.lc.fn_alertMsg
        $c.lc.fn_alertMsg('S1');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf07341.trs_Save_onsuccess" });
    }
};

/**
 * @method
 * @name btn_init_onclick
 * @description 「[없음]」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_init_onclick = function () {
    try {
        scwin.dts_examprn.setCellData(1, "ACCSS_POSBL_IP_LIST_CONTN", "");

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07341.btn_init_onclick' }); }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description btn_Close 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
    try {
        $c.win.closePopup();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07341.btn_Close_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_script_dts_examprn
 * @description script dts examprn 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_script_dts_examprn = async function () {
    $c.util.getComponent("dma_scriptDtsExamprnReq").set("SCREN_ID", "ULDSTF07341.gfm");
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD, INTEG_USR_ID"
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD, INTEG_USR_ID", unresolved: "query_param:SCREN_PROCES_TP_CD,INTEG_USR_ID" };
    const sbmOptions = {
        id: "tx_script_dts_examprn",
        method: "post",
        action: "/konex/InvstgAssgn.do",
        ref: "dma_scriptDtsExamprnReq",
        target: "dtsExamprn=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_examprn_onloaderror'] === 'function') ? scwin['dts_examprn_onloaderror'] : (typeof scwin['dts_examprn_onfail'] === 'function') ? scwin['dts_examprn_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_examprn_onloadcompleted'] === 'function') ? scwin['dts_examprn_onloadcompleted'] : ((typeof scwin['dts_examprn_onsuccess'] === 'function') ? scwin['dts_examprn_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dtsExamprn'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07341.tx_script_dts_examprn" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name sbm_trs_Save
 * @description trs Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sbm_trs_Save = async function () {
    const sbmOptions = {
        id: "sbm_trs_Save",
        method: "post",
        action: "/konex/InvstgAssgn.do",
        ref: "dma_sbmTrs_SaveReq",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['trs_Save_onloaderror'] === 'function') ? scwin['trs_Save_onloaderror'] : (typeof scwin['trs_Save_onfail'] === 'function') ? scwin['trs_Save_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['trs_Save_onloadcompleted'] === 'function') ? scwin['trs_Save_onloadcompleted'] : ((typeof scwin['trs_Save_onsuccess'] === 'function') ? scwin['trs_Save_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('trs_Save'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07341.sbm_trs_Save" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name parentRefresh
 * @description parent Refresh 처리
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function () {
    const fr_fn_list_sync = $c.win.getParent().fn_list_sync;
    fr_fn_list_sync();
};
// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
